<?php
/** Telegram registration administration console (review-only phase). */
declare(strict_types=1);
require_once __DIR__.'/config.php';
if(!function_exists('isLoggedIn')||!isLoggedIn()){header('Location: index.php');exit;}
$role=(string)($_SESSION['admin_role']??'');
if(!in_array($role,['super_admin','school_admin','hr_dept'],true)){http_response_code(403);echo 'Access denied.';exit;}
$canManage=in_array($role,['super_admin','school_admin'],true);
$csrf=generateCsrfToken();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Telegram Registration</title>
<style>
:root{--bg:#f4f7fb;--card:#fff;--text:#172033;--muted:#667085;--line:#e5eaf1;--brand:#1677ff;--ok:#067647;--warn:#b54708;--bad:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1280px;margin:auto;padding:24px}.top{display:flex;gap:16px;align-items:center;justify-content:space-between}.top h1{margin:0;font-size:26px}.sub{color:var(--muted)}.tabs{display:flex;gap:6px;overflow:auto;margin:22px 0}.tab,.btn{border:1px solid var(--line);background:#fff;border-radius:9px;padding:9px 13px;cursor:pointer;color:var(--text)}.tab.active,.btn.primary{background:var(--brand);color:#fff;border-color:var(--brand)}.panel{display:none}.panel.active{display:block}.grid{display:grid;grid-template-columns:repeat(5,minmax(140px,1fr));gap:12px}.card{background:var(--card);border:1px solid var(--line);border-radius:13px;padding:16px;box-shadow:0 2px 8px #1018280a}.metric b{font-size:25px;display:block}.metric span,.hint{color:var(--muted)}.health{display:flex;gap:9px;flex-wrap:wrap;margin-top:14px}.pill{border-radius:999px;padding:5px 9px;background:#f2f4f7}.pill.ok{color:var(--ok);background:#ecfdf3}.pill.bad{color:var(--bad);background:#fef3f2}.toolbar{display:flex;gap:8px;justify-content:space-between;align-items:center;margin-bottom:12px}.tablebox{overflow:auto}.table{width:100%;border-collapse:collapse;background:#fff}.table th,.table td{padding:11px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}.table th{font-size:12px;color:var(--muted);background:#f9fafb}.empty{text-align:center;padding:35px;color:var(--muted)}dialog{border:0;border-radius:14px;padding:0;width:min(620px,94vw);box-shadow:0 20px 60px #10182855}dialog::backdrop{background:#10182888}.modal{padding:20px}.form{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{display:flex;flex-direction:column;gap:5px}.field.full{grid-column:1/-1}input,select{padding:10px;border:1px solid #cfd6e3;border-radius:8px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.notice{padding:12px;border-radius:9px;background:#fffaeb;color:var(--warn);margin:12px 0}.error{background:#fef3f2;color:var(--bad)}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.wrap{padding:14px}.form{grid-template-columns:1fr}}
</style></head><body><main class="wrap">
<div class="top"><div><h1>Telegram Registration</h1><div class="sub">Authorized operator setup, configurable forms, review drafts, duplicate signals and health.</div></div><a class="btn" href="/admin/">Back to admin</a></div>
<div id="message"></div>
<nav class="tabs" aria-label="Telegram administration"><button class="tab active" data-tab="overview">Overview</button><button class="tab" data-tab="operators">Operators</button><button class="tab" data-tab="forms">Forms</button><button class="tab" data-tab="sessions">Sessions & reviews</button><button class="tab" data-tab="audit">Audit</button></nav>
<section class="panel active" id="overview"><div class="grid" id="metrics"></div><div class="card" style="margin-top:12px"><h3>Deployment health</h3><div class="health" id="health"></div><p class="hint">Credentials are deployment-local and are never displayed here. Development, FKSS and WBSS must use different bots and secrets.</p><?php if($role==='super_admin'):?><button class="btn" id="backfill">Run next 100-member identity backfill batch</button><span class="hint" id="backfillStatus"></span><?php endif;?></div></section>
<section class="panel" id="operators"><div class="toolbar"><div><b>Allowed Telegram accounts</b><div class="hint">Every numeric Telegram ID must link to an active HR/admin web account.</div></div><?php if($canManage):?><button class="btn primary" id="addOperator">Add or link operator</button><?php endif;?></div><div class="card tablebox"><table class="table"><thead><tr><th>Telegram ID</th><th>Name</th><th>Linked account</th><th>Role</th><th>Status</th><th>Permissions</th><th>Last seen</th></tr></thead><tbody id="operatorRows"></tbody></table></div></section>
<section class="panel" id="forms"><div class="notice">Published forms are immutable snapshots for active drafts. Editing and publishing controls will be added in the next increment.</div><div class="card tablebox"><table class="table"><thead><tr><th>Profile</th><th>Version</th><th>Status</th><th>Amharic title</th><th>English title</th><th>Enabled</th><th>Required</th></tr></thead><tbody id="formRows"></tbody></table></div></section>
<section class="panel" id="sessions"><div class="toolbar"><b>Registration sessions and HR review drafts</b><select id="sessionStatus"><option value="">All statuses</option><option>review</option><option>submitted</option><option>collecting</option><option>failed</option><option>cancelled</option></select></div><div class="notice">Phase 1 does not create members. Submitted drafts await a separately controlled HR review workflow.</div><div class="card tablebox"><table class="table"><thead><tr><th>Draft</th><th>Type</th><th>Status</th><th>Duplicate signal</th><th>Operator</th><th>Updated</th></tr></thead><tbody id="sessionRows"></tbody></table></div></section>
<section class="panel" id="audit"><div class="card tablebox"><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Event</th><th>Entity</th><th>Result</th></tr></thead><tbody id="auditRows"></tbody></table></div></section>
</main>
<?php if($canManage):?><dialog id="operatorDialog"><form class="modal" id="operatorForm"><h2>Link Telegram operator</h2><input type="hidden" name="action" value="operator_save"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><div class="form"><label class="field full">Numeric Telegram user ID<input name="telegram_user_id" inputmode="numeric" pattern="[0-9]+" required></label><label class="field full">Active HR/admin web-account ID<input name="linked_user_id" inputmode="numeric" pattern="[0-9]+" required></label><label class="field">Status<select name="operator_status"><option value="active">Active</option><option value="suspended">Suspended</option><option value="revoked">Revoked</option></select></label><label class="field">Daily draft limit<input type="number" name="daily_registration_limit" min="1" max="200" value="50"></label><label><input type="checkbox" name="can_waiting" value="1" checked> Temporary/waiting</label><label><input type="checkbox" name="can_direct" value="1"> Direct registration</label></div><div class="actions"><button type="button" class="btn" id="cancelOperator">Cancel</button><button class="btn primary">Save operator</button></div></form></dialog><?php endif;?>
<script>
const API='api_telegram_registration.php', CSRF=<?=json_encode($csrf)?>; const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,options={}){const q=options.query?'&'+new URLSearchParams(options.query):'';const r=await fetch(`${API}?action=${encodeURIComponent(action)}${q}`,{credentials:'same-origin',...options});const j=await r.json().catch(()=>({status:'error',message:'Invalid server response'}));if(!r.ok||j.status!=='success')throw new Error(j.message||'Request failed');return j}
function rows(id,data,render,span){document.getElementById(id).innerHTML=data.length?data.map(render).join(''):`<tr><td colspan="${span}" class="empty">No records found.</td></tr>`}
function showError(e){document.getElementById('message').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}
async function loadOverview(){const j=await api('overview');const s=j.stats;document.getElementById('metrics').innerHTML=[['Operators',s.operators],['Active',s.active_operators],['Open sessions',s.open_sessions],['Submitted drafts',s.submitted],['Failed updates (24h)',s.failed_updates_24h]].map(x=>`<div class="card metric"><b>${esc(x[1])}</b><span>${esc(x[0])}</span></div>`).join('');const checks=[['Migration 080',j.available],['Feature enabled',j.feature_enabled],['Bot token configured',j.secrets.bot_token],['Webhook secret configured',j.secrets.webhook_secret],['Canonical columns',j.canonical_columns]];document.getElementById('health').innerHTML=checks.map(x=>`<span class="pill ${x[1]?'ok':'bad'}">${x[1]?'✓':'×'} ${esc(x[0])}</span>`).join('')}
async function loadOperators(){const j=await api('operators');rows('operatorRows',j.operators,r=>`<tr><td>${esc(r.telegram_user_id)}</td><td>${esc(r.display_name||'Pending first contact')}</td><td>${esc(r.linked_user_name||r.linked_username||'—')}</td><td>${esc(r.linked_role||'—')}</td><td>${esc(r.status)}</td><td>${r.can_waiting==1?'Waiting ':''}${r.can_direct==1?'Direct':''}</td><td>${esc(r.last_seen_at||'Never')}</td></tr>`,7)}
async function loadForms(){const j=await api('forms');rows('formRows',j.forms,r=>`<tr><td>${esc(r.profile_key)}</td><td>${esc(r.version)}</td><td>${esc(r.status)}</td><td>${esc(r.title_am)}</td><td>${esc(r.title_en)}</td><td>${esc(r.enabled_count)}/${esc(r.field_count)}</td><td>${esc(r.required_count)}</td></tr>`,7)}
async function loadSessions(){const status=document.getElementById('sessionStatus').value;const j=await api('sessions',{query:{status}});rows('sessionRows',j.sessions,r=>`<tr><td>${esc(r.public_id)}</td><td>${esc(r.profile_key||'Choosing')}</td><td>${esc(r.status)}</td><td>${esc(r.duplicate_state)}</td><td>${esc(r.operator_name||r.telegram_user_id)}</td><td>${esc(r.updated_at)}</td></tr>`,6)}
async function loadAudit(){const j=await api('audit');rows('auditRows',j.audit,r=>`<tr><td>${esc(r.created_at)}</td><td>${esc(r.actor_type)} #${esc(r.actor_id||'—')}</td><td>${esc(r.event)}</td><td>${esc(r.entity_type||'—')} #${esc(r.entity_id||'—')}</td><td>${esc(r.result)}</td></tr>`,5)}
const loaders={overview:loadOverview,operators:loadOperators,forms:loadForms,sessions:loadSessions,audit:loadAudit};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active');loaders[b.dataset.tab]().catch(showError)});document.getElementById('sessionStatus').onchange=()=>loadSessions().catch(showError);
<?php if($canManage):?>const dlg=document.getElementById('operatorDialog');document.getElementById('addOperator').onclick=()=>dlg.showModal();document.getElementById('cancelOperator').onclick=()=>dlg.close();document.getElementById('operatorForm').onsubmit=async e=>{e.preventDefault();try{const body=new FormData(e.target);await api('operator_save',{method:'POST',body});dlg.close();e.target.reset();await loadOperators()}catch(x){showError(x)}};<?php endif;?>
<?php if($role==='super_admin'):?>document.getElementById('backfill').onclick=async()=>{const el=document.getElementById('backfillStatus');try{const body=new FormData();body.set('action','canonical_backfill');body.set('csrf_token',CSRF);body.set('limit','100');const j=await api('canonical_backfill',{method:'POST',body});el.textContent=` Processed ${j.backfill.processed}; next cursor ${j.backfill.next_cursor}; ${j.backfill.done?'complete':'more remain'}.`}catch(e){showError(e)}};<?php endif;?>
loadOverview().catch(showError);
</script></body></html>